def minCrossingTime(times):
    t = sorted(times)
    n = len(t)
    total = 0
    while n > 3:
        total += min(t[0] + 2 * t[1] + t[n - 1], 2 * t[0] + t[n - 2] + t[n - 1])
        n -= 2
    if n == 3:
        total += t[0] + t[1] + t[2]
    elif n == 2:
        total += t[1]
    elif n == 1:
        total += t[0]
    return total
